package paradox.dl;
import org.junit.*;import static org.junit.Assert.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;import com.sun.net.httpserver.*;
public class EngineIdentityTest {
 @Test public void selectedClientAgentAndUnchangedSignedQueryReachServer()throws Exception{byte[] data=new byte[42751];new Random(14).nextBytes(data);HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);AtomicInteger seen=new AtomicInteger();server.createContext("/audio",e->{if(!"exact-player-client/1.02".equals(e.getRequestHeaders().getFirst("User-Agent"))||!"signed=KEEP%2BME&c=VISIONOS".equals(e.getRequestURI().getRawQuery())){e.sendResponseHeaders(403,-1);e.close();return;}seen.incrementAndGet();String[] pair=e.getRequestHeaders().getFirst("Range").substring(6).split("-");int a=Integer.parseInt(pair[0]),b=Integer.parseInt(pair[1]);e.getResponseHeaders().add("Content-Type","audio/mp4");e.getResponseHeaders().add("Content-Range","bytes "+a+"-"+b+"/"+data.length);e.sendResponseHeaders(206,b-a+1);try(OutputStream o=e.getResponseBody()){o.write(data,a,b-a+1);}});server.start();String url="http://127.0.0.1:"+server.getAddress().getPort()+"/audio?signed=KEEP%2BME&c=VISIONOS";File out=new File(Files.createTempDirectory("dl14-agent").toFile(),"nested/song.part");try{new Engine().run(new Engine.UrlSource(){public String url(int p){return url;}public String refresh(int p){return url;}public String userAgent(int p){return "exact-player-client/1.02";}},new long[]{data.length},new File[]{out});assertArrayEquals(data,Files.readAllBytes(out.toPath()));assertEquals(1,seen.get());}finally{server.stop(0);}}
 @Test public void refreshUpdatesAgentWithUrl()throws Exception{byte[] data=new byte[12345];HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);AtomicInteger refresh=new AtomicInteger(),rejected=new AtomicInteger();server.createContext("/audio",e->{if(!"new-client".equals(e.getRequestHeaders().getFirst("User-Agent"))){rejected.incrementAndGet();e.sendResponseHeaders(403,-1);e.close();return;}e.getResponseHeaders().add("Content-Type","audio/mp4");e.getResponseHeaders().add("Content-Range","bytes 0-12344/12345");e.sendResponseHeaders(206,data.length);try(OutputStream o=e.getResponseBody()){o.write(data);}});server.start();String url="http://127.0.0.1:"+server.getAddress().getPort()+"/audio";File out=Files.createTempFile("dl14-refresh",".part").toFile();try{new Engine().run(new Engine.UrlSource(){public String url(int p){return url;}public String refresh(int p){refresh.incrementAndGet();return url;}public String userAgent(int p){return refresh.get()==0?"old-client":"new-client";}},new long[]{data.length},new File[]{out});assertEquals(1,refresh.get());assertEquals(1,rejected.get());assertArrayEquals(data,Files.readAllBytes(out.toPath()));}finally{server.stop(0);}}
 @Test public void googleUrlIsNotMutatedByRange()throws Exception{String url="https://rr1.googlevideo.com/videoplayback?sig=KEEP%2BX&range=0-99";HttpURLConnection c=Engine.open(url,10,20,"client");try{assertEquals(url,c.getURL().toString());assertEquals("bytes=10-20",c.getRequestProperty("Range"));assertEquals("client",c.getRequestProperty("User-Agent"));}finally{c.disconnect();}}
}
